/**
 * 🌷 THIỆP 20/11 - "GỬI CÔ GIÁO BẠN TÔI"
 * Script tương tác, Canvas animation, Web Audio và Trạng thái
 */

document.addEventListener('DOMContentLoaded', () => {

  // ================= 1. CANVAS MƯA HOA RƠI LIÊN TỤC & HOA NỞ BUNG KHI ẤN =================
  const canvas = document.getElementById('bg-canvas');
  const ctx = canvas.getContext('2d');

  let width = (canvas.width = window.innerWidth);
  let height = (canvas.height = window.innerHeight);

  window.addEventListener('resize', () => {
    width = canvas.width = window.innerWidth;
    height = canvas.height = window.innerHeight;
  });

  const FLOWER_TYPES = ['sakura', 'daisy', 'rosePetal', 'buttercup', 'peachPetal', 'star'];
  const particles = [];
  const burstParticles = [];
  const TOTAL_FALLING = 48; // Hoa rơi liên tục với mật độ phong phú

  // Hàm vẽ các loại hoa nghệ thuật
  function drawSingleFlower(ctx, type, size, color) {
    if (type === 'sakura') {
      // Hoa anh đào 5 cánh hồng
      ctx.fillStyle = color || '#ffccd5';
      for (let i = 0; i < 5; i++) {
        ctx.rotate((Math.PI * 2) / 5);
        ctx.beginPath();
        ctx.ellipse(0, size * 0.45, size * 0.22, size * 0.4, 0, 0, Math.PI * 2);
        ctx.fill();
      }
      // Nhụy hoa
      ctx.beginPath();
      ctx.arc(0, 0, size * 0.18, 0, Math.PI * 2);
      ctx.fillStyle = '#ff758f';
      ctx.fill();
    } else if (type === 'daisy') {
      // Hoa cúc họa mi trắng cánh thon nhụy vàng
      ctx.fillStyle = '#ffffff';
      for (let i = 0; i < 8; i++) {
        ctx.rotate((Math.PI * 2) / 8);
        ctx.beginPath();
        ctx.ellipse(0, size * 0.45, size * 0.14, size * 0.38, 0, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.beginPath();
      ctx.arc(0, 0, size * 0.22, 0, Math.PI * 2);
      ctx.fillStyle = '#ffd166';
      ctx.fill();
    } else if (type === 'buttercup') {
      // Bông hoa cúc vàng rực rỡ
      ctx.fillStyle = '#ffe066';
      for (let i = 0; i < 6; i++) {
        ctx.rotate((Math.PI * 2) / 6);
        ctx.beginPath();
        ctx.arc(0, size * 0.35, size * 0.22, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.beginPath();
      ctx.arc(0, 0, size * 0.2, 0, Math.PI * 2);
      ctx.fillStyle = '#f77f00';
      ctx.fill();
    } else if (type === 'rosePetal') {
      // Cánh hoa hồng cong mềm
      ctx.fillStyle = color || '#ff758f';
      ctx.beginPath();
      ctx.moveTo(0, -size * 0.5);
      ctx.bezierCurveTo(size * 0.6, -size * 0.5, size * 0.7, size * 0.4, 0, size * 0.6);
      ctx.bezierCurveTo(-size * 0.7, size * 0.4, -size * 0.6, -size * 0.5, 0, -size * 0.5);
      ctx.fill();
    } else if (type === 'peachPetal') {
      // Cánh hoa đào uốn lượn
      ctx.fillStyle = color || '#ffb4a2';
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.bezierCurveTo(size * 0.5, -size * 0.5, size, 0, 0, size);
      ctx.bezierCurveTo(-size, 0, -size * 0.5, -size * 0.5, 0, 0);
      ctx.fill();
    } else {
      // Ngôi sao nhỏ lấp lánh (dành tặng icon sao DGH)
      ctx.fillStyle = '#ffd166';
      ctx.beginPath();
      for (let i = 0; i < 5; i++) {
        ctx.lineTo(Math.cos(((18 + i * 72) * Math.PI) / 180) * size * 0.5, -Math.sin(((18 + i * 72) * Math.PI) / 180) * size * 0.5);
        ctx.lineTo(Math.cos(((54 + i * 72) * Math.PI) / 180) * size * 0.25, -Math.sin(((54 + i * 72) * Math.PI) / 180) * size * 0.25);
      }
      ctx.closePath();
      ctx.fill();
    }
  }

  // 1.1. Lớp hoa rơi liên tục
  class FallingFlower {
    constructor() {
      this.reset(true);
    }

    reset(initial = false) {
      this.x = Math.random() * width;
      this.y = initial ? Math.random() * height : -30;
      this.size = Math.random() * 12 + 10;
      this.speedY = Math.random() * 1.3 + 0.9;
      this.speedX = Math.sin(Math.random() * Math.PI * 2) * 1.1;
      this.rotation = Math.random() * 360;
      this.rotationSpeed = (Math.random() - 0.5) * 1.8;
      this.type = FLOWER_TYPES[Math.floor(Math.random() * FLOWER_TYPES.length)];
      this.opacity = Math.random() * 0.45 + 0.55;
      this.color = ['#ffccd5', '#ffe3d8', '#ffd166', '#ffb4a2', '#f4978e', '#ffffff'][
        Math.floor(Math.random() * 6)
      ];
    }

    update() {
      this.y += this.speedY;
      this.x += this.speedX + Math.sin(this.y * 0.012) * 0.7;
      this.rotation += this.rotationSpeed;

      if (this.y > height + 30 || this.x < -30 || this.x > width + 30) {
        this.reset();
      }
    }

    draw() {
      ctx.save();
      ctx.translate(this.x, this.y);
      ctx.rotate((this.rotation * Math.PI) / 180);
      ctx.globalAlpha = this.opacity;
      drawSingleFlower(ctx, this.type, this.size, this.color);
      ctx.restore();
    }
  }

  // 1.2. Lớp hoa nở bung tỏa khi người dùng nhấp chuột
  class BurstFlower {
    constructor(x, y) {
      this.x = x;
      this.y = y;
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 7 + 2.5;
      this.vx = Math.cos(angle) * speed;
      this.vy = Math.sin(angle) * speed - (Math.random() * 2 + 1.5); // Hơi tung lên
      this.size = Math.random() * 14 + 10;
      this.gravity = 0.13;
      this.friction = 0.96;
      this.rotation = Math.random() * 360;
      this.rotationSpeed = (Math.random() - 0.5) * 6;
      this.opacity = 1;
      this.fadeRate = Math.random() * 0.018 + 0.012;
      this.type = FLOWER_TYPES[Math.floor(Math.random() * FLOWER_TYPES.length)];
      this.color = ['#ff4d6d', '#ff758f', '#ffaa95', '#ffd166', '#ffffff', '#ffccd5'][
        Math.floor(Math.random() * 6)
      ];
    }

    update() {
      this.x += this.vx;
      this.y += this.vy;
      this.vy += this.gravity;
      this.vx *= this.friction;
      this.vy *= this.friction;
      this.rotation += this.rotationSpeed;
      this.opacity -= this.fadeRate;
      this.size *= 0.992;
      return this.opacity > 0;
    }

    draw() {
      ctx.save();
      ctx.translate(this.x, this.y);
      ctx.rotate((this.rotation * Math.PI) / 180);
      ctx.globalAlpha = Math.max(0, this.opacity);
      drawSingleFlower(ctx, this.type, this.size, this.color);
      ctx.restore();
    }
  }

  // Khởi tạo mưa hoa rơi liên tục
  for (let i = 0; i < TOTAL_FALLING; i++) {
    particles.push(new FallingFlower());
  }

  // Hàm kích hoạt hiệu ứng hoa nở bung tỏa từ 1 điểm
  function triggerFlowerBurst(x, y, count = 26) {
    for (let i = 0; i < count; i++) {
      burstParticles.push(new BurstFlower(x, y));
    }
  }

  // Vòng lặp render liên tục
  function renderAllParticles() {
    ctx.clearRect(0, 0, width, height);

    // 1. Vẽ hoa rơi
    for (const p of particles) {
      p.update();
      p.draw();
    }

    // 2. Vẽ hoa nở tỏa ra khi ấn
    for (let i = burstParticles.length - 1; i >= 0; i--) {
      const b = burstParticles[i];
      if (b.update()) {
        b.draw();
      } else {
        burstParticles.splice(i, 1);
      }
    }

    requestAnimationFrame(renderAllParticles);
  }
  renderAllParticles();

  // Bắt sự kiện Click / Chạm vào bất kỳ vị trí nào trên màn hình để hoa nở bung tỏa!
  window.addEventListener('pointerdown', (e) => {
    // Không nổ khi bấm vào các nút điều khiển âm thanh hoặc input
    const tag = e.target.tagName.toLowerCase();
    if (tag === 'input' || tag === 'textarea') return;

    triggerFlowerBurst(e.clientX, e.clientY, 24);
    spawnFloatingEmoji('🌸');
  });


  // ================= 2. HIỆU ỨNG MỞ PHONG BÌ (ENVELOPE TO CARD) =================
  const envelopeBox = document.getElementById('envelopeBox');
  const envelopeScreen = document.getElementById('envelopeScreen');
  const mainCard = document.getElementById('mainCard');
  const replayBtn = document.getElementById('replayBtn');

  function openEnvelope() {
    if (envelopeBox.classList.contains('opened')) return;

    envelopeBox.classList.add('opened');
    triggerConfetti(window.innerWidth / 2, window.innerHeight / 2);

    setTimeout(() => {
      envelopeScreen.classList.add('fade-out');

      setTimeout(() => {
        envelopeScreen.style.display = 'none';
        mainCard.classList.remove('hidden');
        // Trigger reflow
        void mainCard.offsetWidth;
        mainCard.classList.add('visible');
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }, 500);
    }, 1100);
  }

  envelopeBox.addEventListener('click', openEnvelope);

  // Xem lại từ đầu
  replayBtn.addEventListener('click', () => {
    mainCard.classList.remove('visible');
    setTimeout(() => {
      mainCard.classList.add('hidden');
      envelopeScreen.style.display = 'flex';
      envelopeScreen.classList.remove('fade-out');
      envelopeBox.classList.remove('opened');
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }, 400);
  });


  // ================= 3. HIỆU ỨNG NỞ HOA TOÀN DIỆN KHI ẤN NÚT =================
  const bloomAllBtn = document.getElementById('bloomAllBtn');
  if (bloomAllBtn) {
    bloomAllBtn.addEventListener('click', (e) => {
      e.stopPropagation();

      // Bùng nổ 5 đợt hoa nở rộ khắp màn hình
      const points = [
        { x: window.innerWidth * 0.2, y: window.innerHeight * 0.3 },
        { x: window.innerWidth * 0.8, y: window.innerHeight * 0.3 },
        { x: window.innerWidth * 0.5, y: window.innerHeight * 0.5 },
        { x: window.innerWidth * 0.3, y: window.innerHeight * 0.7 },
        { x: window.innerWidth * 0.7, y: window.innerHeight * 0.7 }
      ];

      points.forEach((pt, index) => {
        setTimeout(() => {
          triggerFlowerBurst(pt.x, pt.y, 35);
          triggerConfetti(pt.x, pt.y);
        }, index * 120);
      });

      // Bắn các emoji hoa
      ['🌸', '🌷', '🌼', '✨', '💐'].forEach((f, i) => {
        setTimeout(() => spawnFloatingEmoji(f), i * 150);
      });

      showToast('Ngàn đóa hoa tươi thắm đang nở rộ vì Yuki! 🌸✨');
    });
  }

  // Hiệu ứng emoji bay lên
  function spawnFloatingEmoji(emojiChar) {
    const el = document.createElement('div');
    el.innerText = emojiChar;
    el.style.position = 'fixed';
    el.style.left = Math.random() * (window.innerWidth - 60) + 30 + 'px';
    el.style.bottom = '100px';
    el.style.fontSize = Math.random() * 20 + 26 + 'px';
    el.style.pointerEvents = 'none';
    el.style.zIndex = '9999';
    el.style.transition = 'all 1.6s cubic-bezier(0.1, 0.8, 0.3, 1)';
    el.style.opacity = '1';
    document.body.appendChild(el);

    setTimeout(() => {
      el.style.transform = `translateY(-${Math.random() * 200 + 180}px) scale(1.4) rotate(${Math.random() * 60 - 30}deg)`;
      el.style.opacity = '0';
    }, 20);

    setTimeout(() => el.remove(), 1700);
  }


  // ================= 6. ĐỔI TÊN NGƯỜI NHẬN & THAY ẢNH POLAROID =================
  const friendNameDisplay = document.getElementById('friendNameDisplay');
  const photoUploadInput = document.getElementById('photoUploadInput');
  const friendPhoto = document.getElementById('friendPhoto');
  const resetPhotoBtn = document.getElementById('resetPhotoBtn');
  const DEFAULT_PHOTO_PATH = 'assets/friend.jpg';

  // Chuỗi Data URL dự phòng trực tiếp (Đảm bảo ảnh luôn hiển thị kể cả khi GitHub thiếu thư mục assets)
  const DEFAULT_PHOTO_FALLBACK = 'data:image/jpeg;base64,';

  // Xử lý tự động khi ảnh bị 404 (do GitHub thiếu folder assets hoặc phân biệt chữ hoa/thường)
  if (friendPhoto) {
    friendPhoto.addEventListener('error', function () {
      if (!this.dataset.fallbackStep) {
        this.dataset.fallbackStep = 'root';
        this.src = './friend.jpg';
      } else if (this.dataset.fallbackStep === 'root') {
        this.dataset.fallbackStep = 'embedded';
        this.src = DEFAULT_PHOTO_FALLBACK;
      }
    });
  }

  // Khôi phục dữ liệu đã lưu nếu có (nếu chưa có thì dùng mặc định)
  const savedName = localStorage.getItem('teacher_friend_name');
  if (savedName && savedName.trim() !== '') {
    friendNameDisplay.textContent = savedName;
  }

  const savedPhoto = localStorage.getItem('teacher_friend_photo');
  if (savedPhoto && !savedPhoto.includes('unsplash.com')) {
    friendPhoto.src = savedPhoto;
    if (resetPhotoBtn) resetPhotoBtn.style.display = 'inline-flex';
  } else {
    friendPhoto.src = DEFAULT_PHOTO_PATH;
    if (resetPhotoBtn) resetPhotoBtn.style.display = 'none';
  }

  if (resetPhotoBtn) {
    resetPhotoBtn.addEventListener('click', () => {
      localStorage.removeItem('teacher_friend_photo');
      if (friendPhoto) {
        delete friendPhoto.dataset.fallbackStep;
        friendPhoto.src = DEFAULT_PHOTO_PATH;
      }
      resetPhotoBtn.style.display = 'none';
      photoUploadInput.value = '';
      showToast('Đã khôi phục ảnh mặc định! 🌿');
    });
  }

  friendNameDisplay.addEventListener('click', () => {
    const currentName = friendNameDisplay.textContent.replace(' ✏️', '');
    const newName = prompt('Nhập tên hoặc biệt danh của cô bạn thân yêu:', currentName);
    if (newName && newName.trim()) {
      friendNameDisplay.textContent = newName.trim() + ' ✏️';
      localStorage.setItem('teacher_friend_name', newName.trim() + ' ✏️');
      showToast('Đã cập nhật tên cô bạn thành công! ✨');
    }
  });

  photoUploadInput.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          // Resize & nén nhẹ để luôn lưu được an toàn trong localStorage mà không bị mất khi tải lại
          const maxDim = 900;
          let width = img.width;
          let height = img.height;
          if (width > maxDim || height > maxDim) {
            if (width > height) {
              height = Math.round((height * maxDim) / width);
              width = maxDim;
            } else {
              width = Math.round((width * maxDim) / height);
              height = maxDim;
            }
          }
          const canvas = document.createElement('canvas');
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0, width, height);
          const compressedDataUrl = canvas.toDataURL('image/jpeg', 0.85);

          friendPhoto.src = compressedDataUrl;
          try {
            localStorage.setItem('teacher_friend_photo', compressedDataUrl);
          } catch (err) {
            console.warn('Lỗi lưu ảnh vào localStorage:', err);
          }
          if (resetPhotoBtn) resetPhotoBtn.style.display = 'inline-flex';
          showToast('Đã cập nhật và lưu ảnh thành công! 📸');
        };
        img.src = event.target.result;
      };
      reader.readAsDataURL(file);
    }
  });


  // ================= 7. BẢNG LƯU BÚT MINI (STICKY NOTES) =================
  const noteInput = document.getElementById('noteInput');
  const authorInput = document.getElementById('authorInput');
  const addNoteBtn = document.getElementById('addNoteBtn');
  const notesGrid = document.getElementById('notesGrid');

  const noteColors = ['note-yellow', 'note-pink', 'note-green'];

  addNoteBtn.addEventListener('click', () => {
    const text = noteInput.value.trim();
    const author = authorInput.value.trim() || 'DGH';

    if (!text) {
      showToast('Vui lòng nhập vài dòng nhắn nhủ nhé!');
      noteInput.focus();
      return;
    }

    const randomColor = noteColors[Math.floor(Math.random() * noteColors.length)];
    const randomTilt = (Math.random() * 4 - 2).toFixed(1);

    const noteCard = document.createElement('div');
    noteCard.className = `sticky-note ${randomColor}`;
    noteCard.style.transform = `rotate(${randomTilt}deg)`;

    noteCard.innerHTML = `
      <div class="note-pin">📌</div>
      <p class="note-text">"${escapeHtml(text)}"</p>
      <span class="note-author">— ${escapeHtml(author)}</span>
    `;

    notesGrid.prepend(noteCard);
    noteInput.value = '';
    authorInput.value = '';

    spawnFloatingEmoji('💌');
    showToast('Đã dán lời chúc lên bảng thành công! 🎉');
  });

  function escapeHtml(str) {
    return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }


  // ================= 8. TIỆN ÍCH CONFETTI & TOAST NOTIFICATION =================
  function showToast(msg) {
    const toast = document.getElementById('toast');
    toast.textContent = msg;
    toast.classList.add('show');
    setTimeout(() => {
      toast.classList.remove('show');
    }, 2800);
  }

  function triggerConfetti(originX, originY) {
    const count = 40;
    const colors = ['#ff758f', '#ffccd5', '#ffd166', '#52b788', '#fff1b8', '#a2d2ff'];

    for (let i = 0; i < count; i++) {
      const el = document.createElement('div');
      el.style.position = 'fixed';
      el.style.left = originX + 'px';
      el.style.top = originY + 'px';
      el.style.width = Math.random() * 8 + 6 + 'px';
      el.style.height = Math.random() * 8 + 6 + 'px';
      el.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
      el.style.borderRadius = Math.random() > 0.5 ? '50%' : '2px';
      el.style.pointerEvents = 'none';
      el.style.zIndex = '9999';
      el.style.transition = 'all 1.2s cubic-bezier(0.25, 1, 0.5, 1)';
      document.body.appendChild(el);

      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * 160 + 80;
      const targetX = Math.cos(angle) * velocity;
      const targetY = Math.sin(angle) * velocity + 60; // Thêm trọng lực nhẹ

      setTimeout(() => {
        el.style.transform = `translate(${targetX}px, ${targetY}px) rotate(${Math.random() * 360}deg) scale(0)`;
        el.style.opacity = '0';
      }, 20);

      setTimeout(() => el.remove(), 1300);
    }
  }

});
